-- Italské názvy a popisy surovin pro katalog na webu (/it/suroviny).
-- Přeloženo z českých řádků food_translations; appka sama je nevyrábí,
-- nová surovina v appce spadne na webu na angličtinu (viz src/lib/foods.ts).
-- Idempotentní: řádek se vloží jen tam, kde italský překlad ještě není.

insert into public.food_translations (food_id, locale, name, description)
select v.food_id::uuid, 'it', v.name, v.description
from (values
  ('29309265-98fe-48df-ab2b-cf366109d04a', $t$Acciughe (alici)$t$, $t$Acciughe (alici) – piccoli pesci grassi di mare ricchi di omega-3 e calcio (si mangiano interi). Usare fresche/congelate, non sotto sale. Pesce grasso di mare, preziosa fonte di omega-3 e vitamina D. Da inserire 1–2 volte a settimana.$t$),
  ('a0000006-0000-0000-0000-000000000003', $t$Banana$t$, $t$Banana – frutto dolce ricco di potassio. Quantità molto piccole. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('c689b537-46e6-45e2-9afc-a310893e6d7c', $t$Patate dolci$t$, $t$Patate dolci – fonte di fibre e betacarotene. Servire cotte. Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('6051e9b5-863b-4631-8ad4-3e5dda636b4c', $t$Yogurt bianco$t$, $t$Yogurt bianco – probiotici e calcio. Piccole quantità. Integrazione lattiero-casearia – solo piccole quantità, alcuni cani tollerano male il lattosio. Fonte di proteine e calcio.$t$),
  ('a0000006-0000-0000-0000-000000000002', $t$Mirtilli$t$, $t$Mirtilli – antiossidanti, snack piccolo ideale. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('a0000005-0000-0000-0000-000000000002', $t$Broccoli$t$, $t$Broccoli – crucifera con vitamina C. Solo piccole quantità. Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('fb1b6b73-6cf9-4060-85bc-f747d54d384a', $t$Sedano da costa$t$, $t$Sedano da costa – verdura succosa e ipocalorica con fibre. Tagliare finemente o frullare (coste fibrose). Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('76ebab08-3cc8-4db3-af20-febdb22d4b50', $t$Ribes nero$t$, $t$Ribes nero – bacche scure con un contenuto eccezionalmente alto di vitamina C. Ribes, non uva – sicuro in piccole quantità. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('6f014bae-e624-452e-a44e-c19e35e86d05', $t$Ribes rosso$t$, $t$Ribes rosso – bacche acidule ricche di vitamina C e fibre. Il ribes non è uva, per i cani è sicuro in piccole quantità. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('a0000005-0000-0000-0000-000000000003', $t$Zucchina$t$, $t$Zucchina – verdura leggera, ben digeribile e povera di calorie. Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('0c85323f-f4b7-420d-aeee-f5075540d621', $t$Carne di daino$t$, $t$Carne di daino – selvaggina magra. Base della razione – costituisce il 50–70 % della parte carnea. Se la selvaggina non proviene da una fonte verificata (es. dal supermercato), meglio cuocerla.$t$),
  ('702a5427-731f-4730-8f64-7efd6289ac10', $t$Cinghiale$t$, $t$Cinghiale – carne di selvaggina scura. Congelare per la malattia di Aujeszky e le trichine. Base della razione – costituisce il 50–70 % della parte carnea. Se la selvaggina non proviene da una fonte verificata (es. dal supermercato), meglio cuocerla.$t$),
  ('16d2ff5e-eadc-4bfd-ad6b-081e7b14cc9a', $t$Zucca$t$, $t$Zucca – fibre delicate, favorisce la digestione. Servire cotta. Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('19aea7c3-4afb-4e44-9713-577739581ec8', $t$Trippa di manzo$t$, $t$Trippa di manzo – il rumine verde non lavato favorisce digestione e microbioma. Stomaco (trippa) – verde e non lavata è ottima per la digestione e il microbioma. Conta come carne muscolare.$t$),
  ('a0000004-0000-0000-0000-000000000002', $t$Fegato di manzo$t$, $t$Fegato di manzo – la fonte di fegato classica e più comune nel BARF. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('e1b1a750-4fbf-4aae-9268-48e42b6799b6', $t$Lingua di manzo$t$, $t$Lingua di manzo – carne muscolare più grassa, conta come carne. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('a0000003-0000-0000-0000-000000000003', $t$Reni di manzo$t$, $t$Reni di manzo – organo secretore ricco di selenio e vitamine B. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('d5b54d70-b04c-4e41-b3f8-e6cf43a8b0a8', $t$Guance di manzo$t$, $t$Guance di manzo – muscolo da lavoro, magre e succose. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('dfe72b7d-72a0-46b2-a91e-9363997b2a49', $t$Osso con midollo di manzo$t$, $t$Osso con midollo di manzo – osso portante molto duro, solo da rosicchiare. Osso portante più duro – più da rosicchiare che da mangiare. SEMPRE crudo, controlla l'usura dei denti.$t$),
  ('1395dd80-e114-4772-af5b-27900c91b465', $t$Cervello di manzo$t$, $t$Cervello di manzo – fonte di grassi buoni e DHA. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('f3249739-7cd5-4a86-a39d-f724e019a0e6', $t$Coda di manzo$t$, $t$Coda di manzo – osso carnoso con cartilagine, fonte di collagene. Osso portante più duro – più da rosicchiare che da mangiare. SEMPRE crudo, controlla l'usura dei denti.$t$),
  ('a0000003-0000-0000-0000-000000000004', $t$Polmone di manzo$t$, $t$Polmone di manzo – organo leggero e magro. Da dare come complemento della parte carnea, apprezzato anche essiccato come snack.$t$),
  ('aaf196f4-c2ea-4251-bf7a-a286ed463234', $t$Trachea di manzo$t$, $t$Trachea di manzo – cartilagine con glucosamina, ottimo snack da masticare. Parte cartilaginea – fonte naturale di glucosamina e condroitina per le articolazioni. Snack da masticare molto apprezzato.$t$),
  ('9acb18fb-345e-4b90-9dfa-1572ee0d4c80', $t$Milza di manzo$t$, $t$Milza di manzo – organo secretore molto ricco di ferro. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('3f9c2160-688e-4799-8c46-e968d7098af8', $t$Pancreas di manzo$t$, $t$Pancreas di manzo – organo secretore, enzimi naturali (adatto in caso di IPE). Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('a0000003-0000-0000-0000-000000000002', $t$Cuore di manzo$t$, $t$Cuore di manzo – ottima fonte di taurina, economico. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('a0000001-0000-0000-0000-000000000002', $t$Carne muscolare di manzo$t$, $t$Carne muscolare di manzo – la carne magra di base della razione BARF. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('56778459-2e46-48e7-bc0b-9c66363f028a', $t$Mammella di manzo$t$, $t$Mammella di manzo – carne muscolare complementare grassa. Conta come carne muscolare, non come frattaglia – non ha vitamina A, rame né selenio come fegato o reni. Poche proteine e molto grasso, quindi solo per variare – non sostituisce la carne di manzo.$t$),
  ('45ce601b-9401-40c7-bbce-cd0e0be3e84e', $t$Pera$t$, $t$Pera – frutto succoso con fibre. Senza torsolo. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('adfbf92d-ab6a-4667-8bbb-c4f11c9456d1', $t$Fegato d'oca$t$, $t$Fegato d'oca – grasso e ricco, solo in piccole quantità. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('50cd76c8-593c-4209-adf0-288ddacdc443', $t$Colli d'oca$t$, $t$Colli d'oca – osso commestibile grande e più grasso. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('1ac34fa5-d58e-4174-8e68-4d60bd04719a', $t$Carne d'oca$t$, $t$Carne d'oca – pollame più grasso, sapore intenso. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('a0000006-0000-0000-0000-000000000001', $t$Mela$t$, $t$Mela – fonte di fibre e vitamina C. Togliere il torsolo (i semi contengono cianuro). Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('2bf512d2-fe48-40b4-a185-3148bbf4b741', $t$Fragole$t$, $t$Fragole – vitamina C e fibre, come snack. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('7164342c-b939-45eb-b9aa-871d02c062e8', $t$Fegato d'agnello$t$, $t$Fegato d'agnello – ricco di rame e vitamina A. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('d35ddd87-a7b9-43cf-9455-3ab48b9c9ee6', $t$Lingua d'agnello$t$, $t$Lingua d'agnello – carne muscolare più grassa. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('ee19cd47-c739-4e64-a446-b33795e3d842', $t$Reni d'agnello$t$, $t$Reni d'agnello – reni più piccoli e delicati. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('a0000001-0000-0000-0000-000000000004', $t$Carne d'agnello$t$, $t$Carne d'agnello – carne rossa più grassa dal sapore deciso. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('07e8641d-d73b-44d1-b437-057fbde6e71b', $t$Polmone d'agnello$t$, $t$Polmone d'agnello – organo leggero, apprezzato come snack essiccato. Organo leggero e magro. Da dare come complemento della parte carnea, apprezzato anche essiccato come snack.$t$),
  ('f925dca9-49b2-4c90-a1a9-ed4fb158c7bd', $t$Cuore d'agnello$t$, $t$Cuore d'agnello – cuore più piccolo, ideale per cani di taglia media. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('3c87d0ca-fee4-45ac-853a-bc90a308dcef', $t$Costine d'agnello$t$, $t$Costine d'agnello – osso commestibile con uno strato di carne e grasso. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('fc9b60eb-dc25-43c2-bae7-6e5502792888', $t$Fegato di cervo$t$, $t$Fegato di cervo – fegato di selvaggina, ricco di nutrienti. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('ed329b3b-fb4e-41cb-b303-1da314174fc4', $t$Fegato d'anatra$t$, $t$Fegato d'anatra – fegato di pollame più grasso. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('c74f3c78-af49-48a4-9eee-590b7eacc587', $t$Ali d'anatra$t$, $t$Ali d'anatra – osso commestibile carnoso. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000002-0000-0000-0000-000000000003', $t$Colli d'anatra$t$, $t$Colli d'anatra – osso commestibile più grande per cani di taglia media e grande. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000001-0000-0000-0000-000000000005', $t$Petto d'anatra$t$, $t$Petto d'anatra – carne di pollame scura più magra. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('a4f6cd41-cea7-4fa5-adfc-3b11c0b64dc0', $t$Carcasse d'anatra$t$, $t$Carcasse d'anatra – carcassa più grassa con cartilagine. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('2e3cc505-ceb6-4c91-87c7-efbaba617d87', $t$Cuori d'anatra$t$, $t$Cuori d'anatra – piccolo organo muscolare con taurina. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('53361084-adb1-43de-8ac2-ac73025ccd1c', $t$Ventrigli d'anatra$t$, $t$Ventrigli d'anatra – muscolosi e gustosi. Ventriglio muscoloso, conta come carne muscolare. Naturalmente ricco di proteine.$t$),
  ('8a817089-1223-4042-8ea3-e01e0e265b78', $t$Fegato di cavallo$t$, $t$Fegato di cavallo – magro e ricco di ferro. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('e36871a2-7e20-4c68-90d9-0df96ec31118', $t$Carne di cavallo$t$, $t$Carne di cavallo – magra, ipoallergenica, adatta in caso di allergie. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('f81d67a3-a49e-49f3-af72-27ee577c3ed0', $t$Cuore di cavallo$t$, $t$Cuore di cavallo – organo muscolare magro. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('1f48fd0f-78a3-4091-8c7b-49e39bc39c3c', $t$Carne di capra$t$, $t$Carne di capra – carne rossa magra, poco allergenica. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('0236d8aa-8504-4618-94ea-a37b83a6a572', $t$Fegato di coniglio$t$, $t$Fegato di coniglio – fegato magro di una carne magra. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('1ef4deb1-21c7-44a0-9215-8d6350bf5d6b', $t$Carne di coniglio$t$, $t$Carne di coniglio – magra e facilmente digeribile, ipoallergenica. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('53081f21-372e-44e9-87bb-d933f5f475e1', $t$Coniglio intero (con osso)$t$, $t$Coniglio intero con osso – preda completa: carne muscolare, ossa commestibili e frattaglie insieme. L'app lo ripartisce all'incirca in 60 % carne muscolare, 30 % ossa e 10 % frattaglie. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('dc010526-9f58-49cb-8ff1-adb082496379', $t$Quaglia (intera)$t$, $t$Quaglia intera – piccola preda completa con ossa e organi. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('20e99202-683d-4dce-97ce-7e29b616f3e1', $t$Fegato di tacchino$t$, $t$Fegato di tacchino – fonte di fegato da pollame. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('68f7535a-d943-4647-92b2-ae4116ca009f', $t$Ali di tacchino$t$, $t$Ali di tacchino – osso commestibile carnoso per cani più grandi. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('c4e9cc16-dd6a-4fef-b83e-2bcf2a6cf127', $t$Colli di tacchino$t$, $t$Colli di tacchino – osso commestibile grande per cani grandi. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000001-0000-0000-0000-000000000003', $t$Petto di tacchino$t$, $t$Petto di tacchino – carne bianca molto magra. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('c416d378-17da-493a-a961-4346c65ca704', $t$Cuore di tacchino$t$, $t$Cuore di tacchino – organo muscolare ricco di taurina. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('45c82f5d-99ad-4f15-b714-2ba229bf308d', $t$Coscia di tacchino$t$, $t$Coscia di tacchino – carne più scura e un po' più grassa. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('8c2ad4ff-590b-49d4-ad24-00c4ddf6425c', $t$Ventrigli di tacchino$t$, $t$Ventrigli di tacchino – organo muscoloso, conta come carne muscolare. Ventriglio muscoloso, conta come carne muscolare. Naturalmente ricco di proteine.$t$),
  ('a0000002-0000-0000-0000-000000000002', $t$Dorsi di pollo$t$, $t$Dorsi di pollo con cartilagine e residui di carne. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000004-0000-0000-0000-000000000001', $t$Fegato di pollo$t$, $t$Fegato di pollo – morbido e facile da reperire, adatto ai cani piccoli. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('6fa17f82-6bfe-4071-b9ff-eaf134ded315', $t$Ali di pollo$t$, $t$Ali di pollo – osso commestibile ben digeribile. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000002-0000-0000-0000-000000000001', $t$Colli di pollo$t$, $t$Colli di pollo morbidi, osso commestibile ideale per cani piccoli e medi. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('e7d8fcb4-ae47-46c1-89ec-f4324a565e4c', $t$Zampe di pollo$t$, $t$Zampe di pollo – fonte naturale di glucosamina, snack apprezzato. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000001-0000-0000-0000-000000000001', $t$Petto di pollo$t$, $t$Petto di pollo – carne bianca magra, base per cani sensibili. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('8086894d-8fb1-4590-bcf2-a88b9cede648', $t$Carcasse di pollo$t$, $t$Carcasse di pollo (scheletri) dopo il disosso, con cartilagine e residui di carne. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('a0000003-0000-0000-0000-000000000001', $t$Cuori di pollo$t$, $t$Cuori di pollo – cuoricini, fonte di taurina apprezzata. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('a4b3be39-3cc1-4583-8cd7-7610b627ef70', $t$Coscia di pollo$t$, $t$Coscia di pollo – carne più scura e succosa. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('a824dddb-fd60-4bb3-870c-c2f9501de3ad', $t$Ventrigli di pollo$t$, $t$Ventrigli di pollo – muscolosi, contano come carne muscolare. Ventriglio muscoloso, conta come carne muscolare. Naturalmente ricco di proteine.$t$),
  ('7f31950d-8120-4e40-a229-5937b1731d79', $t$Cavolfiore$t$, $t$Cavolfiore – crucifera con vitamina C e folati. Meglio leggermente cotto al vapore. Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('b6e5ab5e-544b-4e68-9490-0d1c1c79bee5', $t$Salmone$t$, $t$Salmone – pesce grasso ricco di omega-3. Congelato almeno 3 settimane per i parassiti. Pesce grasso di mare, preziosa fonte di omega-3 e vitamina D. Da inserire 1–2 volte a settimana.$t$),
  ('a0000007-0000-0000-0000-000000000001', $t$Olio di salmone$t$, $t$Olio di salmone – fonte liquida di omega-3 per pelo e articolazioni. Integrazione di acidi grassi omega-3 per pelo e articolazioni. Da qualche goccia a qualche ml al giorno in base alla taglia del cane.$t$),
  ('0ebe106b-b2c4-4273-937a-3f34bdd94f3b', $t$Sgombro$t$, $t$Sgombro – pesce grasso di mare con omega-3. Pesce grasso di mare, preziosa fonte di omega-3 e vitamina D. Da inserire 1–2 volte a settimana.$t$),
  ('0943f697-a6db-4de0-baf6-62df039a0328', $t$Lamponi$t$, $t$Lamponi – bacche ricche di fibre e vitamina C. Solo piccole quantità (contengono tracce di xilitolo). Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('4d946245-2f63-4a2b-876b-53c526b7384b', $t$Guscio d'uovo macinato$t$, $t$Guscio d'uovo macinato – calcio puro per razioni senza ossa. Integrazione di calcio per razioni senza ossa. Circa 1 g (½ cucchiaino) ogni 500 g di carne.$t$),
  ('5d14b3ac-b118-4cb2-8a3a-0625ee499265', $t$Alga marina$t$, $t$Alga marina – fonte naturale di iodio. Solo un pizzico. Fonte naturale di iodio per la tiroide. Solo un pizzico – è facile eccedere con lo iodio.$t$),
  ('a0000005-0000-0000-0000-000000000001', $t$Carota$t$, $t$Carota – betacarotene e fibre, apprezzata anche cruda da sgranocchiare. Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('1dc17ceb-c3cb-4328-af14-51131bc06525', $t$More$t$, $t$More – bacche scure con antiossidanti e fibre. Snack piccolo ideale. Frutta solo come snack occasionale in piccole quantità per il contenuto di zuccheri.$t$),
  ('b2f1e6a4-7c3d-4b8e-9a12-5f7c9d0e1a23', $t$Porro$t$, $t$Porro – ortaggio del genere Allium. ATTENZIONE: il porro è tossico per i cani (come cipolla e aglio) – danneggia i globuli rossi e può causare anemia emolitica. Sconsigliato, anche cotto.$t$),
  ('c815843e-9614-4cb4-bd19-df93b3f0726d', $t$Alga nori$t$, $t$Alga nori – alga marina con iodio e vitamina A, più delicata del kelp. Dare solo piccole quantità. Fonte naturale di iodio per la tiroide. Solo piccole quantità – è facile eccedere con lo iodio.$t$),
  ('b1668561-d079-4ee0-a6b7-df9ccf3286dd', $t$Sardine$t$, $t$Sardine – piccoli pesci di mare, interi con le lische. Pesce grasso di mare, preziosa fonte di omega-3 e vitamina D. Da inserire 1–2 volte a settimana.$t$),
  ('d3c9da3b-e70e-42f7-b815-f019d1d97461', $t$Aringa$t$, $t$Aringa – pesce grasso di mare, fonte di omega-3 e vitamina D. Pesce grasso di mare, preziosa fonte di omega-3 e vitamina D. Da inserire 1–2 volte a settimana.$t$),
  ('a0000005-0000-0000-0000-000000000004', $t$Spinaci$t$, $t$Spinaci – verdura a foglia ricca di ferro. Con moderazione (ossalati). Verdura – circa il 10 % della razione. Per una migliore digeribilità frullare o cuocere leggermente al vapore.$t$),
  ('8c40218d-0b9e-49c5-b376-34b3dd3e58bf', $t$Carne di capriolo$t$, $t$Carne di capriolo – selvaggina delicata e magra. Base della razione – costituisce il 50–70 % della parte carnea. Se la selvaggina non proviene da una fonte verificata (es. dal supermercato), meglio cuocerla.$t$),
  ('4258ea8a-cbdb-4349-9b8b-c5714717f8f0', $t$Fegato di vitello$t$, $t$Fegato di vitello – più delicato e leggero di quello di manzo. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('f1085f36-49e8-4bf6-93e6-206687616f05', $t$Carne muscolare di vitello$t$, $t$Carne muscolare di vitello – carne delicata e magra. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('17da90b5-de38-41bd-bbe7-e0a4efb2ec67', $t$Quark (formaggio fresco)$t$, $t$Quark (formaggio fresco) – proteine leggere e calcio. Integrazione lattiero-casearia – solo piccole quantità, alcuni cani tollerano male il lattosio. Fonte di proteine e calcio.$t$),
  ('a0000007-0000-0000-0000-000000000002', $t$Uovo$t$, $t$Uovo – proteina completa; con il guscio anche fonte di calcio. Uovo intero con il guscio – proteina completa e calcio. 2–3 volte a settimana in base alla taglia del cane.$t$),
  ('6dff6fc2-dfdd-40cb-9de2-4ac3864885c3', $t$Diaframma di maiale$t$, $t$Diaframma di maiale – muscolo sottile del diaframma, carne muscolare gustosa. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('bb8a8f3d-c79d-4ee3-a03b-40943c8e46bb', $t$Testa di maiale$t$, $t$Testa di maiale – carne, cartilagine e osso insieme. Osso portante più duro – più da rosicchiare che da mangiare. SEMPRE crudo, controlla l'usura dei denti.$t$),
  ('5cfdf04b-cfba-4cd7-b52e-0dcb6a3844f1', $t$Fegato di maiale$t$, $t$Fegato di maiale – fonte di fegato facile da reperire, sapore intenso. L'organo più importante nel BARF, estremamente ricco di vitamina A, rame e ferro. Max 5 % della razione, altrimenti c'è il rischio di sovradosaggio di vitamina A.$t$),
  ('af918a13-86cd-4a50-bac8-88b550b4a5a9', $t$Coppa di maiale$t$, $t$Coppa di maiale – taglio più succoso e marezzato. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('835bf3b4-0ed7-41f5-a780-0acaef4c3590', $t$Coscia di maiale$t$, $t$Coscia di maiale – taglio posteriore più magro. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('59676165-74e0-4e97-993e-2ce4aa470717', $t$Guance di maiale$t$, $t$Guance di maiale – muscolo da lavoro succoso. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('80f5f491-4091-4b6f-8a93-b30db86cc90a', $t$Osso con midollo di maiale$t$, $t$Osso con midollo di maiale – osso portante duro, da rosicchiare. Osso portante più duro – più da rosicchiare che da mangiare. SEMPRE crudo, controlla l'usura dei denti.$t$),
  ('754de29a-cd26-406f-86cd-2c5a82d8ea5d', $t$Filetto di maiale$t$, $t$Filetto di maiale – il taglio di maiale più magro. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('0e056f3b-1cb6-4453-bf8d-1e6029246a46', $t$Lonza di maiale (braciola)$t$, $t$Lonza di maiale (braciola) – carne magra del dorso. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('c6d2374c-71f7-4f34-a816-f259c96e7448', $t$Spalla di maiale$t$, $t$Spalla di maiale – taglio mediamente grasso. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('1588c11d-3a4d-4ee7-bdb8-13999488b15c', $t$Milza di maiale$t$, $t$Milza di maiale – organo ricco di ferro. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('381853bc-32bc-4e3c-842c-f588fd652fd7', $t$Pancreas di maiale$t$, $t$Pancreas di maiale – fonte di enzimi digestivi. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('d5b2b7e3-34e8-4846-812b-da1ea3131e01', $t$Carne muscolare di maiale$t$, $t$Carne muscolare di maiale – carne di maiale generica. Sempre ben congelata (Aujeszky). Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('cc786e81-634e-4aba-acf1-de134cd83850', $t$Costine di maiale$t$, $t$Costine di maiale – osso commestibile carnoso. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('4224fc51-d21a-4c08-ad09-2e20d29f6bec', $t$Stinco di maiale$t$, $t$Stinco di maiale – osso portante più duro con carne. Osso portante più duro – più da rosicchiare che da mangiare. SEMPRE crudo, controlla l'usura dei denti.$t$),
  ('876caa4e-47a0-4ac0-b524-2f5d72aacb97', $t$Reni di maiale$t$, $t$Reni di maiale – organo secretore facile da reperire. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('01ffd839-64be-4c08-b7e6-05e49bbc9961', $t$Zampetti di maiale$t$, $t$Zampetti di maiale – pelle, cartilagine e osso, fonte di collagene. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('79930f0f-64d7-4f43-a080-8b0f7e2dbd8f', $t$Polmone di maiale$t$, $t$Polmone di maiale – organo leggero e magro. Da dare come complemento della parte carnea, apprezzato anche essiccato come snack.$t$),
  ('ef60c485-97b6-4285-b971-92663e5dfd57', $t$Strutto$t$, $t$Strutto – grasso animale puro, energia concentrata. Grasso puro – fonte concentrata di energia. Usare con moderazione, soprattutto per cani attivi o denutriti.$t$),
  ('b5129d74-6082-416d-a926-d3512ebd7381', $t$Cuore di maiale$t$, $t$Cuore di maiale – organo muscolare con taurina. Organo muscolare ricco di taurina – conta come carne muscolare, non come frattaglia. Fino al 10–15 % della razione.$t$),
  ('4746ff20-9eb2-49c5-a856-bf10ed381957', $t$Orecchie di maiale$t$, $t$Orecchie di maiale – snack cartilagineo da rosicchiare. Parte cartilaginea – fonte naturale di glucosamina e condroitina per le articolazioni. Snack da masticare molto apprezzato.$t$),
  ('b50e8776-88e4-41b9-b0bd-8898b0de24a7', $t$Animelle di maiale$t$, $t$Animelle di maiale – organo secretore ghiandolare dal sapore delicato. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('3b5e40a9-b3d2-438d-b49f-bb8bede65120', $t$Pancetta di maiale$t$, $t$Pancetta di maiale – taglio molto grasso ed energetico. Con moderazione. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('6c21434d-854d-405e-831b-54fe8eb33d95', $t$Lingua di maiale$t$, $t$Lingua di maiale – carne muscolare più grassa. Base della razione – costituisce il 50–70 % della parte carnea.$t$),
  ('e7b543db-0607-4c85-b4a5-eb47289b8784', $t$Cervello di maiale$t$, $t$Cervello di maiale – ricco di grassi e DHA. Organo secretore (frattaglie). Insieme al fegato costituisce circa il 10 % della razione, di cui gli organi diversi dal fegato ~5 %.$t$),
  ('c3268866-3fc0-45ad-86d3-546ad12c8d3f', $t$Codino di maiale$t$, $t$Codino di maiale – osso commestibile grasso con cartilagine. Osso morbido commestibile – fonte di calcio. Costituisce circa il 10–15 % della razione. SEMPRE crudo, mai cotto (le ossa cotte si scheggiano).$t$),
  ('6e8b6695-b121-4fa1-b17e-9fce79b614d1', $t$Stomaco di maiale$t$, $t$Stomaco di maiale – organo muscoloso, sostiene la digestione. Stomaco (trippa) – verde e non lavata è ottima per la digestione e il microbioma. Conta come carne muscolare.$t$),
  ('914c4da0-4e64-4384-b334-59fdbf8516db', $t$Selvaggina (cervo)$t$, $t$Selvaggina (cervo) – carne scura e magra. Base della razione – costituisce il 50–70 % della parte carnea. Se la selvaggina non proviene da una fonte verificata (es. dal supermercato), meglio cuocerla.$t$)
) as v(food_id, name, description)
where not exists (
  select 1 from public.food_translations t where t.food_id = v.food_id::uuid and t.locale = 'it'
);
